sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    if (!current.engine_version) {
        current.engine_version = '1.0.0';
    }
    if (!current.status) {
        current.status = 'proposed';
    }
    if (!current.requestor) {
        current.requestor = gs.getUserID();
    }
})(current, previous);

(function executeRule(current, previous /*null when async*/) {
    if (!current.fingerprint) { return; }
    var gr = new GlideRecord('x_snff_flow_forge_draft');
    gr.addQuery('fingerprint', current.fingerprint);
    gr.addQuery('sys_id', '!=', current.getUniqueValue());
    gr.setLimit(1);
    gr.query();
    if (gr.hasNext()) {
        gr.next();
        gs.log('A draft with the same spec fingerprint already exists (sys_id: ' + gr.getUniqueValue() + ').', 'FlowForge');
    }
})(current, previous);
